bash -lc "cat <<'PY' > main.py
import subprocess,sys

L,R=1,1024
queries=0

def ask(x):
    global queries
    res=subprocess.check_output(['./guess.py',str(x)]).decode().strip()
    queries+=1
    return res

while True:
    if queries>=15:
        print("exhausted", file=sys.stderr)
        break
    if L==R:
        break
    if R-L+1==2:
        # two numbers left, just guess L twice to confirm
        ans=ask(L)
        if ans=='equals':
            L,R=L,L
            break
        ans2=ask(L)
        if ans2=='equals':
            L,R=L,L
            break
        # else assume it's R
        break
    mid=(L+R)//2
    a=ask(mid)
    if a=='equals':
        L=R=mid
        break
    b=ask(mid)
    if a==b:
        if a=='higher':
            L=mid+1
        else:
            R=mid-1
    else:
        # flip, trust first
        if a=='higher':
            L=mid+1
        else:
            R=mid-1

print(max(L,R))
PY

